bool backtrack(int* nums, int numsSize, int k, int target, int start, int currSum, int* used, int usedCount) {
    if (k == 0) return true;
    if (currSum == target) {
        // Start to fill next bucket
        return backtrack(nums, numsSize, k - 1, target, 0, 0, used, usedCount);
    }
    for (int i = start; i < numsSize; i++) {
        if (!used[i] && currSum + nums[i] <= target) {
            used[i] = 1;
            if (backtrack(nums, numsSize, k, target, i + 1, currSum + nums[i], used, usedCount + 1)) {
                return true;
            }
            used[i] = 0;
            // Optimization: if currSum is 0 and nums[i] didn't work, no need to try others at this level
            if (currSum == 0) return false;
        }
    }
    return false;
}

bool canPartitionKSubsets(int* nums, int numsSize, int k){
    int sum = 0;
    for (int i = 0; i < numsSize; i++) sum += nums[i];
    if (sum % k != 0) return false;
    int target = sum / k;

    // Sort nums descending to optimize pruning
    // Simple insertion sort descending
    for (int i = 1; i < numsSize; i++) {
        int key = nums[i];
        int j = i - 1;
        while (j >= 0 && nums[j] < key) {
            nums[j + 1] = nums[j];
            j--;
        }
        nums[j + 1] = key;
    }

    // If largest number > target, no solution
    if (nums[0] > target) return false;

    int used[16] = {0};
    return backtrack(nums, numsSize, k, target, 0, 0, used, 0);
}

